import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { useEffect } from 'react'
import { LayoutChangeEvent, Text } from 'react-native'
import Animated, {
	useAnimatedStyle,
	useSharedValue,
	withTiming
} from 'react-native-reanimated'

type OTPCellProps = {
	symbol: string
	isFocused: boolean
	getCellOnLayoutHandler: (event: LayoutChangeEvent) => void
	otpError: boolean
}

export const OTPCell = ({
	symbol,
	isFocused,
	getCellOnLayoutHandler,
	otpError
}: OTPCellProps) => {
	const { theme, isDark } = useTheme()
	const hasValue = !!symbol
	const cellSizeValue = useSharedValue(12)
	const cellMarginValue = useSharedValue(8)

	useEffect(() => {
		cellSizeValue.set(
			withTiming(hasValue || isFocused ? 52 : 12, {
				duration: 200
			})
		)
		cellMarginValue.set(
			withTiming(hasValue || isFocused ? 4 : 16, {
				duration: 200
			})
		)
	}, [hasValue, cellSizeValue, cellMarginValue, isFocused])

	const cellScaleAnimatedStyle = useAnimatedStyle(() => ({
		width: cellSizeValue.get(),
		height: cellSizeValue.get(),
		marginHorizontal: cellMarginValue.get()
	}))

	return (
		<Animated.View
			style={[
				styles.cellContainer(theme, isDark),
				cellScaleAnimatedStyle,
				otpError
					? styles.otpErrorCellContainer(theme)
					: (isFocused || hasValue) &&
					  styles.focusedCellContainer(theme, isDark)
			]}
		>
			<Text
				style={[
					styles.cellText(theme, isDark),
					otpError && styles.otpErrorCellText(theme)
				]}
				onLayout={getCellOnLayoutHandler}
			>
				{symbol}
			</Text>
		</Animated.View>
	)
}

const styles = defineStyles({
	cellContainer: (theme: Theme, isDark: boolean) => ({
		width: 52,
		height: 52,
		borderRadius: 50,
		backgroundColor: isDark ? colors[theme].gray[75] : colors[theme].gray[50]
	}),
	otpErrorCellContainer: (theme: Theme) => ({
		backgroundColor: colors[theme].red[50]
	}),
	focusedCellContainer: (theme: Theme, isDark: boolean) => ({
		backgroundColor: isDark ? colors[theme].blue[300] : colors[theme].blue[50]
	}),
	cellText: (theme: Theme, isDark: boolean) => ({
		lineHeight: 52,
		fontSize: 24,
		textAlign: 'center',
		color: isDark ? colors[theme].gray[900] : colors[theme].blue[600]
	}),
	otpErrorCellText: (theme: Theme) => ({
		color: colors[theme].red[600]
	})
})
